using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Text.RegularExpressions;
public sealed class GoogleFilePin {public string id="",name="",url="",mimeType="";}
internal static class GoogleFiles {
 internal static bool ValidId(string id){return id!=null&&Regex.IsMatch(id,@"^[a-zA-Z0-9_-]{1,200}$");}
 internal static bool ValidUrl(string url){Uri uri;return Uri.TryCreate(url,UriKind.Absolute,out uri)&&uri.Scheme=="https"&&uri.IsDefaultPort&&uri.UserInfo==""&&(uri.DnsSafeHost=="docs.google.com"||uri.DnsSafeHost=="drive.google.com");}
 internal static GoogleFilePin FromLink(string name,string url){if(String.IsNullOrWhiteSpace(name)||name.Length>200||!ValidUrl(url))throw new InvalidDataException("Indiquez un nom et un lien Google Drive, Docs ou Sheets valide.");var uri=new Uri(url);var parts=uri.AbsolutePath.Split(new[]{'/'},StringSplitOptions.RemoveEmptyEntries);string id="",mime="";int d=Array.IndexOf(parts,"d");if(d>=0&&d+1<parts.Length)id=parts[d+1];int folder=Array.IndexOf(parts,"folders");if(folder>=0&&folder+1<parts.Length){id=parts[folder+1];mime="application/vnd.google-apps.folder";}if(String.IsNullOrEmpty(id))id=System.Web.HttpUtility.ParseQueryString(uri.Query)["id"];if(!ValidId(id))throw new InvalidDataException("Copiez le lien d’un fichier ou d’un dossier Google précis.");if(parts.Contains("spreadsheets"))mime="application/vnd.google-apps.spreadsheet";else if(parts.Contains("document"))mime="application/vnd.google-apps.document";else if(parts.Contains("presentation"))mime="application/vnd.google-apps.presentation";return new GoogleFilePin{id=id,name=name.Trim(),url=url.Trim(),mimeType=mime};}
 internal static string TypeName(string mime){return mime=="application/vnd.google-apps.spreadsheet"?"Google Sheets":mime=="application/vnd.google-apps.document"?"Google Docs":mime=="application/vnd.google-apps.presentation"?"Google Slides":mime=="application/vnd.google-apps.folder"?"Dossier Drive":"Fichier Drive";}
 internal static void Validate(Data d){if(d.googlePins==null)d.googlePins=new List<GoogleFilePin>();if(d.googlePins.Count>500)throw new InvalidDataException("Limite : 500 liens Google enregistrés.");var seen=new HashSet<string>();foreach(var pin in d.googlePins){if(pin==null||!ValidId(pin.id)||String.IsNullOrWhiteSpace(pin.name)||pin.name.Length>200||!ValidUrl(pin.url)||pin.url.Length>2048||!seen.Add(pin.id))throw new InvalidDataException("Lien Google enregistré invalide.");pin.mimeType=pin.mimeType??"";}}
 internal static GoogleFilePin Remember(Data d,GoogleFilePin file){var existing=d.googlePins.FirstOrDefault(p=>p.id==file.id);if(existing==null){if(d.googlePins.Count>=500)throw new InvalidDataException("Limite de liens Google atteinte.");existing=new GoogleFilePin{id=file.id};d.googlePins.Add(existing);}existing.name=file.name;existing.url=file.url;existing.mimeType=file.mimeType;return existing;}
 internal static string Query(string search,bool sheets){string q="trashed = false";if(sheets)q+=" and mimeType = 'application/vnd.google-apps.spreadsheet'";if(!String.IsNullOrWhiteSpace(search))q+=" and name contains '"+search.Trim().Replace("\\","\\\\").Replace("'","\\'")+"'";return q;}
 internal static void Test(string folder){var pin=FromLink("Budget","https://docs.google.com/spreadsheets/d/test_id-123/edit");if(pin.id!="test_id-123"||TypeName(pin.mimeType)!="Google Sheets")throw new Exception("Lien Sheets");bool bad=false;try{FromLink("Faux","https://docs.google.com.attacker.example/spreadsheets/d/test/edit");}catch(InvalidDataException){bad=true;}if(!bad)throw new Exception("Domaine Google non vérifié");if(!Query("l'équipe",true).Contains(@"l\'équipe"))throw new Exception("Échappement recherche Drive");var s=new Store(Path.Combine(folder,"google-pins"));Remember(s.Value,pin);Remember(s.Value,pin);s.Value.favorites.Add(new Favorite{kind="google",id=pin.id,label=pin.name});s.Save();s=new Store(s.Root);if(s.Value.googlePins.Count!=1||GlobalSearch.Resolve(s.Value,s.Value.favorites[0]).Title!="Budget")throw new Exception("Persistance lien Google / favori");s.Export(Path.Combine(folder,"google-pins.json"));s.Value.googlePins.Clear();s.Import(Path.Combine(folder,"google-pins.json"));if(s.Value.googlePins.Count!=1)throw new Exception("Import liens Google");}
}
